  network_all_tx_multicast_octets_actual: { label: "Отправлено многоадресных байтов", hint: "Общее число байтов, отправленных в многоадресных пакетах через этот интерфейс, по подсчёту сетевого драйвера." },
  network_all_tx_broadcast_octets_actual: { label: "Отправлено широковещательных байтов", hint: "Общее число байтов, отправленных в широковещательных пакетах через этот интерфейс, по подсчёту сетевого драйвера." },
